#!/usr/bin/env python3
import base64, gzip, hashlib
from pathlib import Path

CORPUS = {
"prompt-A.txt": "",
"prompt-B.txt": "",
"prompt-C.txt": ""
}

EXPECTED = {
    "prompt-A.txt": "1f579ccf4de99394c78a9ecc58ced8c4c17e65ab6f9ca8fd805242c77dc7631e",
    "prompt-B.txt": "65f17396904bb1e918e2f5879be425121baffa475477a0c57871759d82a1d1d1",
    "prompt-C.txt": "4f23217c4c4889de44279a03f986994d8d9dfe26cc802bbcf2a598aa25ae8654",
}

root = Path(__file__).resolve().parent
for name, encoded in CORPUS.items():
    data = gzip.decompress(base64.b64decode(encoded))
    actual = hashlib.sha256(data).hexdigest()
    if actual != EXPECTED[name]:
        raise SystemExit(f"hash mismatch for {name}: {actual}")
    (root / name).write_bytes(data)
    print(f"wrote {name} sha256={actual}")
